package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api") public class SharedFolderController {
 private final FolderRepository folders;private final SharedFolderMemberRepository members;private final UserRepository users;
 public SharedFolderController(FolderRepository f,SharedFolderMemberRepository m,UserRepository u){folders=f;members=m;users=u;}
 @PatchMapping("/folders/{id}/shared") public ResponseEntity<?> shared(@PathVariable Long id,@RequestBody Map<String,Boolean> body,Authentication a){Folder f=folders.findById(id).filter(x->x.ownerId.equals(owner(a))).orElse(null);if(f==null)return error(404,"Папка не найдена");f.shared=Boolean.TRUE.equals(body.get("is_shared"));folders.save(f);if(!f.shared)members.deleteAll(members.findByIdFolderId(id));return ResponseEntity.ok(Map.of("id",id,"is_shared",f.shared));}
 @GetMapping("/shared") public List<Map<String,Object>> list(Authentication a){Long uid=owner(a);Map<Long,Map<String,Object>> result=new LinkedHashMap<>();for(Folder f:folders.findAll())if(f.shared&&f.ownerId.equals(uid))result.put(f.id,entry(f,uid,true));for(SharedFolderMember m:members.findByIdUserId(uid))folders.findById(m.id.folderId).ifPresent(f->result.put(f.id,entry(f,uid,false)));return new ArrayList<>(result.values());}
 @GetMapping("/shared/{folderId}/members") public ResponseEntity<?> getMembers(@PathVariable Long folderId,Authentication a){if(!canManage(folderId,owner(a)))return error(404,"Папка не найдена");return ResponseEntity.ok(members.findByIdFolderId(folderId).stream().map(this::memberView).toList());}
 @PostMapping("/shared/{folderId}/members") public ResponseEntity<?> addMember(@PathVariable Long folderId,@RequestBody MemberRequest r,Authentication a){if(!canManage(folderId,owner(a)))return error(404,"Папка не найдена");User u=users.findAll().stream().filter(x->x.username.equals(r.username())).findFirst().orElse(null);if(u==null)return error(404,"Пользователь не найден");SharedFolderMember m=new SharedFolderMember();m.id=id(folderId,u.id);apply(m,r);return ResponseEntity.ok(memberView(members.save(m)));}
 @PatchMapping("/shared/{folderId}/members/{userId}") public ResponseEntity<?> update(@PathVariable Long folderId,@PathVariable Long userId,@RequestBody MemberRequest r,Authentication a){if(!canManage(folderId,owner(a)))return error(404,"Папка не найдена");SharedFolderMember m=members.findById(id(folderId,userId)).orElse(null);if(m==null)return error(404,"Участник не найден");apply(m,r);return ResponseEntity.ok(memberView(members.save(m)));}
 @DeleteMapping("/shared/{folderId}/members/{userId}") public ResponseEntity<?> remove(@PathVariable Long folderId,@PathVariable Long userId,Authentication a){if(!canManage(folderId,owner(a)))return error(404,"Папка не найдена");SharedFolderMember m=members.findById(id(folderId,userId)).orElse(null);if(m==null)return error(404,"Участник не найден");members.delete(m);return ResponseEntity.noContent().build();}
 private Map<String,Object> entry(Folder f,Long uid,boolean owner){Map<String,Object> m=new LinkedHashMap<>();m.put("folder_id",f.id);m.put("name",f.name);m.put("owner_username",users.findById(f.ownerId).map(x->x.username).orElse(""));m.put("my_rights",owner?List.of("view","download","upload","delete","rename","manage"):members.findById(id(f.id,uid)).map(x->rights(x)).orElse(List.of()));return m;}
 private List<String> rights(SharedFolderMember x){List<String> r=new ArrayList<>();if(x.canView)r.add("view");if(x.canDownload)r.add("download");if(x.canUpload)r.add("upload");if(x.canDelete)r.add("delete");if(x.canRename)r.add("rename");return r;}
 private Map<String,Object> memberView(SharedFolderMember m){Map<String,Object> v=new LinkedHashMap<>();v.put("user_id",m.id.userId);v.put("username",users.findById(m.id.userId).map(x->x.username).orElse(""));v.put("can_view",m.canView);v.put("can_download",m.canDownload);v.put("can_upload",m.canUpload);v.put("can_delete",m.canDelete);v.put("can_rename",m.canRename);v.put("max_file_size_mb",m.maxFileSizeMb);v.put("max_user_space_mb",m.maxUserSpaceMb);return v;}
 private void apply(SharedFolderMember m,MemberRequest r){m.canView=r.can_view()==null||r.can_view();m.canDownload=Boolean.TRUE.equals(r.can_download());m.canUpload=Boolean.TRUE.equals(r.can_upload());m.canDelete=Boolean.TRUE.equals(r.can_delete());m.canRename=Boolean.TRUE.equals(r.can_rename());m.maxFileSizeMb=r.max_file_size_mb();m.maxUserSpaceMb=r.max_user_space_mb();}
 private boolean canManage(Long folder,Long uid){return folders.findById(folder).filter(f->f.shared&&f.ownerId.equals(uid)).isPresent();} private SharedFolderMemberId id(Long f,Long u){SharedFolderMemberId x=new SharedFolderMemberId();x.folderId=f;x.userId=u;return x;}private Long owner(Authentication a){return ((AuthUser)a.getPrincipal()).id();}private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}public record MemberRequest(String username,Boolean can_view,Boolean can_download,Boolean can_upload,Boolean can_delete,Boolean can_rename,Long max_file_size_mb,Long max_user_space_mb){}
}
